package com.beeboee.magnot.client;import com.beeboee.magnot.Magnot;import com.beeboee.magnot.item.FerrousTubeItem;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.region.FerrousRegion;import com.beeboee.magnot.registry.MagnotItems;import com.mojang.blaze3d.matrix.MatrixStack;import com.mojang.blaze3d.vertex.IVertexBuilder;import net.minecraft.client.Minecraft;import net.minecraft.client.entity.player.ClientPlayerEntity;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.util.*;import net.minecraft.util.math.*;import net.minecraft.util.math.vector.*;import net.minecraft.util.text.*;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.client.event.*;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import java.util.*;
@Mod.EventBusSubscriber(modid=Magnot.MOD_ID,value=Dist.CLIENT,bus=Mod.EventBusSubscriber.Bus.FORGE)public final class MagnotClientEvents{private static final ResourceLocation TEX=new ResourceLocation(Magnot.MOD_ID,"textures/special/ferrous_region.png");private static final Map<Object,State>S=new LinkedHashMap<Object,State>();private static final Object PREVIEW=new Object();private static long last,next;private MagnotClientEvents(){}@SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;for(State s:S.values())s.fresh=false;Minecraft mc=Minecraft.getInstance();ClientPlayerEntity p=mc.player;if(p==null||mc.level==null||p.getMainHandItem().getItem()!=MagnotItems.FERROUS_TUBE.get())return;Optional<FerrousRegion>selected=selected(p);for(FerrousRegion r:ClientRegionStore.all()){if(distanceToBoxSqr(p.position(),r.bounds())>625)continue;boolean active=selected.isPresent()&&selected.get().id().equals(r.id());show(r.id(),r.bounds(),0xBD2537,active);}Optional<BlockPos>a=FerrousTubeItem.first(p.getMainHandItem());if(a.isPresent()&&mc.hitResult instanceof BlockRayTraceResult){BlockPos raw=((BlockRayTraceResult)mc.hitResult).getBlockPos(),b=FerrousTubeItem.clamp(a.get(),raw);int color=FerrousTubeItem.over(a.get(),raw)?0xFFD43B:0xBD2537;p.displayClientMessage(new TranslationTextComponent("message.magnot.click_to_confirm").withStyle(color==0xFFD43B?TextFormatting.YELLOW:TextFormatting.RED),true);show(PREVIEW,FerrousRegion.fromCorners(UUID.randomUUID(),a.get(),b).bounds(),color,true);}}@SubscribeEvent public static void click(InputEvent.ClickInputEvent e){if(!e.isAttack())return;Minecraft mc=Minecraft.getInstance();ClientPlayerEntity p=mc.player;if(p==null||mc.level==null||p.getMainHandItem().getItem()!=MagnotItems.FERROUS_TUBE.get())return;e.setCanceled(true);e.setSwingHand(true);if(mc.level.getGameTime()>=next){next=mc.level.getGameTime()+5;Optional<FerrousRegion>r=selected(p);if(r.isPresent())MagnotNetwork.remove(r.get().id());}}@SubscribeEvent public static void logout(ClientPlayerNetworkEvent.LoggedOutEvent e){ClientRegionStore.clear();S.clear();}@SubscribeEvent public static void render(RenderWorldLastEvent e){if(S.isEmpty())return;long now=System.nanoTime();float dt=last==0?0:Math.min((now-last)/1_000_000_000f,.1f);last=now;Minecraft mc=Minecraft.getInstance();Vector3d cam=mc.gameRenderer.getMainCamera().getPosition();MatrixStack matrix=e.getMatrixStack();IRenderTypeBuffer.Impl buffers=mc.renderBuffers().bufferSource();Iterator<State>it=S.values().iterator();while(it.hasNext()){State s=it.next();if(!s.active)s.strength=Math.max(0,s.strength-dt/.18f);if(!s.fresh&&s.strength<=.001){it.remove();continue;}AxisAlignedBB b=s.box.move(-cam.x,-cam.y,-cam.z);IVertexBuilder lines=buffers.getBuffer(RenderType.lines());WorldRenderer.renderLineBox(matrix,lines,b,(s.color>>16&255)/255f,(s.color>>8&255)/255f,(s.color&255)/255f,1f);if(s.strength>.001)faces(matrix,buffers,b,s);}buffers.endBatch();}private static Optional<FerrousRegion>selected(ClientPlayerEntity p){Vector3d a=p.getEyePosition(1);return ClientRegionStore.selected(a,a.add(p.getLookAngle().scale(6)));}private static void show(Object id,AxisAlignedBB b,int color,boolean active){State s=S.get(id);if(s==null){s=new State();S.put(id,s);}s.box=b;s.color=color;s.active=active;s.fresh=true;if(active)s.strength=1;}private static double distanceToBoxSqr(Vector3d p,AxisAlignedBB b){double x=Math.max(Math.max(b.minX-p.x,0),p.x-b.maxX),y=Math.max(Math.max(b.minY-p.y,0),p.y-b.maxY),z=Math.max(Math.max(b.minZ-p.z,0),p.z-b.maxZ);return x*x+y*y+z*z;}private static void faces(MatrixStack stack,IRenderTypeBuffer.Impl buffers,AxisAlignedBB b,State s){IVertexBuilder v=buffers.getBuffer(RenderType.entityTranslucent(TEX));Matrix4f m=stack.last().pose();Matrix3f n=stack.last().normal();int a=Math.max(1,Math.round(72*s.strength));quad(v,m,n,b.minX,b.minY,b.minZ,b.maxX,b.minY,b.maxZ,s,a);quad(v,m,n,b.minX,b.maxY,b.minZ,b.maxX,b.maxY,b.maxZ,s,a);quad(v,m,n,b.minX,b.minY,b.minZ,b.minX,b.maxY,b.maxZ,s,a);quad(v,m,n,b.maxX,b.minY,b.minZ,b.maxX,b.maxY,b.maxZ,s,a);quad(v,m,n,b.minX,b.minY,b.minZ,b.maxX,b.maxY,b.minZ,s,a);quad(v,m,n,b.minX,b.minY,b.maxZ,b.maxX,b.maxY,b.maxZ,s,a);}private static void quad(IVertexBuilder v,Matrix4f m,Matrix3f n,double x0,double y0,double z0,double x1,double y1,double z1,State s,int a){vert(v,m,n,x0,y0,z0,0,0,s,a);vert(v,m,n,x1,y0,z1,1,0,s,a);vert(v,m,n,x1,y1,z1,1,1,s,a);vert(v,m,n,x0,y1,z0,0,1,s,a);}private static void vert(IVertexBuilder v,Matrix4f m,Matrix3f n,double x,double y,double z,float u,float w,State s,int a){v.vertex(m,(float)x,(float)y,(float)z).color(s.color>>16&255,s.color>>8&255,s.color&255,a).uv(u,w).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(15728880).normal(n,0,1,0).endVertex();}private static final class State{AxisAlignedBB box;int color;boolean active,fresh;float strength;}}
